-- Modify "services" table
ALTER TABLE "public"."services" ALTER COLUMN "public_id" TYPE character varying;
-- Create "svc_clients" table
CREATE TABLE "public"."svc_clients" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "public_id" character varying NOT NULL,
  "secret_hash" bytea NOT NULL,
  "name" character varying NOT NULL,
  "description" character varying NULL,
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "service_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "svc_clients_services_client_apps" FOREIGN KEY ("service_id") REFERENCES "public"."services" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);

-- Create index "svc_clients_public_id_key" to table: "svc_clients"
CREATE UNIQUE INDEX "svc_clients_public_id_key" ON "public"."svc_clients" ("public_id");
-- Create index "svcclient_public_id" to table: "svc_clients"
CREATE UNIQUE INDEX "svcclient_public_id" ON "public"."svc_clients" ("public_id");
-- Create index "svcclient_service_id_name" to table: "svc_clients"
CREATE UNIQUE INDEX "svcclient_service_id_name" ON "public"."svc_clients" ("service_id", "name");

-- Move data from "client_apps" to "svc_clients"
INSERT INTO "public"."svc_clients" ("public_id", "secret_hash", "name", "description", "is_active", "created_at", "updated_at", "service_id")
SELECT "public_id", "secret_hash", "name", "description", "is_active", "created_at", "updated_at", "service_id"
FROM "public"."client_apps";
-- Remove foreign key constraint from "client_apps" table
ALTER TABLE "public"."client_apps" DROP CONSTRAINT "client_apps_services_service_id_fkey";
-- Remove index "client_apps_public_id_key" from "client_apps" table
DROP INDEX "public"."client_apps_public_id_key";
-- Remove index "client_apps_service_id_name" from "client_apps" table
DROP INDEX "public"."client_apps_service_id_name";

-- Drop "client_apps" table
DROP TABLE "public"."client_apps";
